<section class="page-head"><div><span class="eyebrow"><?=e(__('nav.business'))?></span><h1><?=e(__('business.title'))?></h1></div><div class="head-actions"><a class="btn primary" href="<?=e(url('/business/create'))?>"><?=e(__('business.create'))?></a><?php if($products):?><a class="btn ghost" href="<?=e(url('/business/product/create'))?>"><?=e(__('marketplace.add'))?></a><?php endif;?></div></section><div class="split-grid"><section class="panel"><h2><?=e(__('business.title'))?></h2><?php if(!$businesses):?><div class="empty-state compact"><h3><?=e(__('business.empty'))?></h3><p><?=e(__('business.created'))?></p></div><?php else: foreach($businesses as $b):?><div class="list-row"><div><strong><?=e($b['name'])?></strong><small><?=e($b['description']?:'')?></small></div><span class="status <?=e($b['status'])?>"><?=e($b['status'])?></span></div><?php endforeach;endif;?></section><section class="panel"><div class="section-head inline"><div><span class="eyebrow"><?=e(__('ui.products'))?></span><h2><?=e(__('business.products'))?></h2></div><a class="text-link" href="<?=e(url('/business/product/create'))?>">+ <?=e(__('common.create'))?></a></div><?php if(!$products):?><div class="empty-mini"><?=e(__('common.no_results'))?></div><?php else: foreach($products as $p):?><div class="list-row"><div><strong><?=e($p['name'])?></strong><small><?=e($p['business_name'])?></small></div><span><?=e(money($p['base_price']))?></span></div><?php endforeach;endif;?></section></div>
